    var bytesLoaded = event.loaded;
    var bytesTotal = sourceBuffer.bytesTotal;

    // Calculate the percentage of the buffer that is filled
    var fillPercentage = (bytesLoaded / bytesTotal) * 100;

    // If the buffer is nearly full, show the buffering indicator

