import org.springframework.beans.factory.config.BeanFactory;
import org.springframework.beans.factory.config.BeanFactoryAware;
import org.springframework.beans.factory.config.ConfigurableListableBeanFactory;
import org.springframework.beans.factory.support.AbstractBeanFactory;

public class DynamicBeanCreator implements BeanFactoryAware {

    private BeanFactory beanFactory;

    @Override
    public void setBeanFactory(BeanFactory beanFactory) {
        this.beanFactory = beanFactory;
    }

    public void createDynamicBeans(int count, String beanName) {
